import sys
from itertools import combinations

def is_prime(x):
    if x < 2:
        return False
    for i in range(2, int(x**0.5) + 1):
        if x % i == 0:
            return False
    return True

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    k = int(input[1])
    cards = [(int(input[3*i]), int(input[3*i+1]), int(input[3*i+2])) for i in range(n)]

    min_level = -1

    for level in range(1, n + 1):
        valid_cards = [card for card in cards if card[2] <= level]
        for r in range(1, len(valid_cards) + 1):
            for combo in combinations(valid_cards, r):
                if sum(card[0] for card in combo) >= k:
                    if all(not is_prime(card1[1] + card2[1]) for card1, card2 in combinations(combo, 2)):
                        min_level = level
                        break
            if min_level != -1:
                break
        if min_level != -1:
            break

    print(min_level)

if __name__ == "__main__":
    main()
